/**
 * Builds a keyword search index over content sections.
 * Weighted scoring: heading 3x, keyword 2x, body 1x, exact phrase 5x.
 */
function tokenize(text) {
    return text
        .toLowerCase()
        .replace(/[^a-z0-9\s-]/g, ' ')
        .split(/\s+/)
        .filter(w => w.length > 1);
}
function countTerms(tokens) {
    const freq = new Map();
    for (const t of tokens) {
        freq.set(t, (freq.get(t) || 0) + 1);
    }
    return freq;
}
export class SearchIndex {
    entries = [];
    constructor(sections) {
        for (const section of sections) {
            this.entries.push({
                section,
                titleTerms: countTerms(tokenize(section.title)),
                bodyTerms: countTerms(tokenize(section.body)),
                fullText: `${section.title}\n${section.body}`.toLowerCase(),
            });
        }
    }
    /**
     * Search for sections matching the query. Returns top-N results sorted by score.
     */
    search(query, topN = 5) {
        const queryTokens = tokenize(query);
        const queryLower = query.toLowerCase().trim();
        if (queryTokens.length === 0)
            return [];
        const scored = [];
        for (const entry of this.entries) {
            let score = 0;
            // Term matching with weights
            for (const token of queryTokens) {
                const titleHits = entry.titleTerms.get(token) || 0;
                const bodyHits = entry.bodyTerms.get(token) || 0;
                const keywordHits = entry.section.keywords.includes(token) ? 1 : 0;
                score += titleHits * 3;
                score += keywordHits * 2;
                score += bodyHits * 1;
            }
            // Exact phrase bonus (only for multi-word queries)
            if (queryTokens.length > 1 && entry.fullText.includes(queryLower)) {
                score += 5;
            }
            if (score > 0) {
                scored.push({ entry, score });
            }
        }
        scored.sort((a, b) => b.score - a.score);
        return scored.slice(0, topN).map(({ entry, score }) => ({
            title: entry.section.title,
            sourceFile: entry.section.sourceFile,
            preview: entry.section.body.slice(0, 300),
            score,
        }));
    }
}
